/**
 * Original design by Gustavo Fior (@gustavo-fior), co-founder Abdul Haidar, and Foglamp Labs.
 * Extracted AS-IS from foglamp-labs/foglamp: apps/web/src/app/buttons/page.tsx.
 * Licensed under Apache-2.0.
 */
"use client";

import {
	IconArrowRight,
	IconBell,
	IconBellFilled,
	IconBolt,
	IconBoltFilled,
	IconBookmark,
	IconBookmarkFilled,
	IconCamera,
	IconCircleCheckFilled,
	IconClock,
	IconCloud,
	IconCloudFilled,
	IconDownload,
	IconEyeFilled,
	IconFlag,
	IconFlagFilled,
	IconFolder,
	IconFolderFilled,
	IconHeart,
	IconHeartFilled,
	IconHome,
	IconHomeFilled,
	IconMail,
	IconMapPin,
	IconMapPinFilled,
	IconMoon,
	IconMoonFilled,
	IconPlayerPlayFilled,
	IconPlus,
	IconRocket,
	IconSettings,
	IconSettingsFilled,
	IconSparkles,
	IconStar,
	IconStarFilled,
	IconSun,
	IconSunFilled,
	IconThumbUp,
	IconThumbUpFilled,
	IconTrash,
	IconTrashFilled,
} from "@tabler/icons-react";
import { useTheme } from "next-themes";
import { useEffect } from "react";

import { Badge } from "../../ui/badge";
import { Button } from "../../ui/button";

// Dev-only playground for tweaking packages/ui button + badge styles.
// Press T anywhere on the page to flip light/dark.

type IconComponent = typeof IconStar;
type NonEmptyIconPool = readonly [IconComponent, ...IconComponent[]];

const OUTLINED: NonEmptyIconPool = [
	IconStar,
	IconHeart,
	IconPlus,
	IconArrowRight,
	IconDownload,
	IconSettings,
	IconTrash,
	IconBolt,
	IconBell,
	IconBookmark,
	IconCamera,
	IconClock,
	IconCloud,
	IconFlag,
	IconFolder,
	IconHome,
	IconMail,
	IconMapPin,
	IconMoon,
	IconSun,
	IconRocket,
	IconSparkles,
	IconThumbUp,
];

const FILLED: NonEmptyIconPool = [
	IconStarFilled,
	IconHeartFilled,
	IconBellFilled,
	IconBookmarkFilled,
	IconBoltFilled,
	IconCircleCheckFilled,
	IconTrashFilled,
	IconSettingsFilled,
	IconPlayerPlayFilled,
	IconFlagFilled,
	IconFolderFilled,
	IconHomeFilled,
	IconMoonFilled,
	IconSunFilled,
	IconCloudFilled,
	IconMapPinFilled,
	IconEyeFilled,
	IconThumbUpFilled,
];

// Deterministic "random" assignment so server and client render the same
// markup (Math.random would break hydration). Each slot index gets a varied
// icon, alternates filled/outlined, and flips between leading/trailing.
function pick(i: number) {
	const filled = i % 2 === 1;
	const pool = filled ? FILLED : OUTLINED;
  const Icon = pool[(i * 7 + 3) % pool.length] ?? pool[0];
	const leading = i % 3 !== 1;
	return { Icon, leading };
}

const BUTTON_VARIANTS = [
	"default",
	"outline",
	"secondary",
	"ghost",
	"ghost-destructive",
	"destructive",
	"link",
] as const;

const BUTTON_SIZES = ["xs", "sm", "default", "lg"] as const;

const BADGE_VARIANTS = [
	"default",
	"secondary",
	"destructive",
	"outline",
	"green",
	"blue",
	"amber",
	"orange",
	"emerald",
	"rose",
	"red",
	"violet",
	"fuchsia",
	"sky",
] as const;

const BADGE_SIZES = ["md", "lg"] as const;

function useThemeHotkey() {
	const { resolvedTheme, setTheme } = useTheme();

	useEffect(() => {
		const onKey = (e: KeyboardEvent) => {
			if (e.key.toLowerCase() !== "t" || e.metaKey || e.ctrlKey || e.altKey)
				return;
			const target = e.target;
			if (
				target instanceof HTMLElement &&
				(target.isContentEditable ||
					["INPUT", "TEXTAREA", "SELECT"].includes(target.tagName))
			)
				return;
			setTheme(resolvedTheme === "dark" ? "light" : "dark");
		};
		window.addEventListener("keydown", onKey);
		return () => window.removeEventListener("keydown", onKey);
	}, [resolvedTheme, setTheme]);
}

function Row({
	label,
	children,
}: {
	label: string;
	children: React.ReactNode;
}) {
	return (
		<div className="flex items-center gap-3">
			<span className="w-36 shrink-0 font-mono text-xs text-muted-foreground">
				{label}
			</span>
			<div className="flex flex-wrap items-center gap-2">{children}</div>
		</div>
	);
}

export function ButtonsBadgesPlaygroundBlock() {
	useThemeHotkey();

	// Monotonic slot counter across the whole page so no two adjacent
	// buttons/badges draw the same icon.
	let slot = 0;

	return (
		<main className="mx-auto max-w-4xl space-y-12 px-6 py-12">
			<div>
				<h1 className="text-lg font-semibold">Buttons & badges playground</h1>
				<p className="text-sm text-muted-foreground">
					Press <kbd className="rounded border px-1 font-mono text-xs">T</kbd>{" "}
					to toggle the theme
				</p>
			</div>

			<section className="space-y-4">
				<h2 className="text-sm font-semibold text-muted-foreground">Buttons</h2>
				<div className="space-y-3">
					{BUTTON_VARIANTS.map((variant) => (
						<Row key={variant} label={variant}>
							{BUTTON_SIZES.map((size) => {
								const { Icon, leading } = pick(slot++);
								return (
									<Button key={size} variant={variant} size={size}>
										{leading && <Icon />}
										Button
										{!leading && <Icon />}
									</Button>
								);
							})}
						</Row>
					))}
				</div>
			</section>

			<section className="space-y-4">
				<h2 className="text-sm font-semibold text-muted-foreground">Badges</h2>
				<div className="space-y-3">
					{BADGE_VARIANTS.map((variant) => (
						<Row key={variant} label={variant}>
							{BADGE_SIZES.map((size) => {
								const { Icon, leading } = pick(slot++);
								return (
									<Badge key={size} variant={variant} size={size}>
										{leading && <Icon />}
										Badge
										{!leading && <Icon />}
									</Badge>
								);
							})}
						</Row>
					))}
				</div>
			</section>
		</main>
	);
}

/**
 * Original design by Gustavo Fior (@gustavo-fior), co-founder Abdul Haidar, and Foglamp Labs.
 * Extracted AS-IS from foglamp-labs/foglamp: apps/web/src/components/device-approve-client.tsx.
 * Licensed under Apache-2.0.
 */
"use client";

import { Button } from "../../ui/button";
import { Input } from "../../ui/input";
import { Label } from "../../ui/label";
import {
	IconCircleCheckFilled,
	IconCircleXFilled,
} from "@tabler/icons-react";
import { useCallback, useEffect, useRef, useState } from "react";

import { BrandMark } from "../marketing/chrome/brand-mark";
import { Card } from "../../ui/card";

// The verification step of `npx foglamp login`. The CLI prints a URL that lands
// the user here (already signed in — the page gates that). We first "claim" the
// user code for this account (GET /device), then let them approve or deny. On
// approve the CLI's token poll succeeds and it mints a key + writes .env.

type Phase =
	| "claiming" // verifying the code belongs to a live request
	| "ready" // claimed + pending — show approve/deny
	| "approved"
	| "denied"
	| "needCode" // no/blank code in the URL — ask the user to paste it
	| "error";

export type DeviceClaimResult =
	| { kind: "pending" }
	| { kind: "approved" }
	| { kind: "denied" }
	| { kind: "error"; message: string };

export type DeviceDecisionResult =
	| { kind: "success" }
	| { kind: "error"; message: string };

export type DeviceApproveBlockProps = {
	initialUserCode: string;
	userEmail?: string | null;
	onClaim?: (input: {
		userCode: string;
		userEmail?: string | null;
	}) => Promise<DeviceClaimResult>;
	onDecision?: (input: {
		userCode: string;
		action: "approve" | "deny";
	}) => Promise<DeviceDecisionResult>;
	onApproved?: (input: { userCode: string }) => void;
};

const LOCAL_PENDING_CLAIM: DeviceClaimResult = { kind: "pending" };
const LOCAL_SUCCESSFUL_DECISION: DeviceDecisionResult = { kind: "success" };

function getErrorMessage(error: unknown, fallback: string): string {
	return error instanceof Error && error.message ? error.message : fallback;
}

// Module-level so it keeps a stable identity across renders — a component
// defined inside DeviceApprove would remount its subtree on every keystroke
// (and the code input would lose focus).
function DeviceShell({ children }: { children: React.ReactNode }) {
	return (
		<div className="mx-auto flex w-full max-w-lg flex-col p-6">
			<div className="size-10 rounded-md squircle:rounded-2xl corner-squircle bg-muted shadow-(--custom-shadow) flex justify-center items-center">
				<BrandMark className="w-7" />
			</div>
			{children}
		</div>
	);
}

export function DeviceApproveBlock({
	initialUserCode,
	userEmail,
	onClaim,
	onDecision,
	onApproved,
}: DeviceApproveBlockProps) {
	const [code, setCode] = useState(initialUserCode.trim());
	const [phase, setPhase] = useState<Phase>(
		initialUserCode.trim() ? "claiming" : "needCode",
	);
	const [message, setMessage] = useState<string | null>(null);
	const [busy, setBusy] = useState(false);

	// Claim the code: associates it with the signed-in user and returns its
	// current status. Approve/deny both require this first (the server rejects an
	// unclaimed code), so it runs before we show the approve button.
	const claim = useCallback(async (userCode: string) => {
		setPhase("claiming");
		setMessage(null);
		try {
			const result = onClaim
				? await onClaim({ userCode, userEmail })
				: LOCAL_PENDING_CLAIM;
			switch (result.kind) {
				case "approved":
					setPhase("approved");
					break;
				case "denied":
					setPhase("denied");
					break;
				case "error":
					setPhase("error");
					setMessage(result.message);
					break;
				case "pending":
					setPhase("ready");
					break;
				default: {
					const exhaustive: never = result;
					return exhaustive;
				}
			}
		} catch (error) {
			setPhase("error");
			setMessage(
				getErrorMessage(error, "That code is invalid or has expired."),
			);
		}
	}, [onClaim, userEmail]);

	// Claim once on mount when the code arrived in the URL. Guard against the
	// effect firing twice (React strict mode) for the same code.
	const claimedFor = useRef<string | null>(null);
	useEffect(() => {
		const c = initialUserCode.trim();
		if (!c || claimedFor.current === c) return;
		claimedFor.current = c;
		void claim(c);
	}, [initialUserCode, claim]);

	const decide = async (action: "approve" | "deny") => {
		setBusy(true);
		try {
			const result = onDecision
				? await onDecision({ userCode: code, action })
				: LOCAL_SUCCESSFUL_DECISION;
			if (result.kind === "error") {
				setPhase("error");
				setMessage(result.message);
				return;
			}
			if (action === "approve") {
				onApproved?.({ userCode: code });
			}
			setPhase(action === "approve" ? "approved" : "denied");
		} catch (error) {
			setPhase("error");
			setMessage(
				getErrorMessage(error, `Could not ${action} the request.`),
			);
		} finally {
			setBusy(false);
		}
	};

	if (phase === "approved") {
		return (
			<DeviceShell>
				<div className="mt-5 flex items-center gap-2">
					<IconCircleCheckFilled className="size-5 text-green-500" />
					<h1 className="text-lg font-medium">Terminal connected</h1>
				</div>
				<p className="mt-2 text-sm text-muted-foreground text-balance">
					{onDecision
						? "You can return to your terminal. Foglamp will finish setting up and write your API key. You can close this tab."
						: "Local demo approval complete. Connect an onDecision callback to authorize a real terminal."}
				</p>
			</DeviceShell>
		);
	}

	if (phase === "denied") {
		return (
			<DeviceShell>
				<div className="mt-5 flex items-center gap-2">
					<IconCircleXFilled className="size-5 text-muted-foreground" />
					<h1 className="text-lg font-medium">Request denied</h1>
				</div>
				<p className="mt-2 text-sm text-muted-foreground text-balance">
					No device was connected. If this was a mistake, run{" "}
					<code>npx foglamp login</code> again to start over.
				</p>
			</DeviceShell>
		);
	}

	if (phase === "error") {
		return (
			<DeviceShell>
				<div className="mt-5 flex items-center gap-2">
					<IconCircleXFilled className="size-5 text-destructive" />
					<h1 className="text-lg font-medium">Couldn’t connect</h1>
				</div>
				<p className="mt-2 text-sm text-muted-foreground text-balance">
					{message ?? "Something went wrong."}
				</p>
				<Button
					variant="secondary"
					className="mt-5 self-start"
					onClick={() => {
						claimedFor.current = null;
						setPhase(code ? "claiming" : "needCode");
						if (code) void claim(code);
					}}
				>
					Try again
				</Button>
			</DeviceShell>
		);
	}

	if (phase === "needCode") {
		return (
			<DeviceShell>
				<h1 className="mt-5 mb-1 text-lg font-medium">Connect your terminal</h1>
				<p className="mb-6 text-sm text-muted-foreground text-balance">
					Enter the code shown by <code>npx foglamp login</code> to continue.
				</p>
				<form
					className="flex flex-col gap-2.5"
					onSubmit={(e) => {
						e.preventDefault();
						const c = code.trim();
						if (c) void claim(c);
					}}
				>
					<Label htmlFor="user_code">Code</Label>
					<Input
						id="user_code"
						autoFocus
						autoComplete="off"
						placeholder="ABCD1234"
						value={code}
						onChange={(e) => setCode(e.target.value)}
						className="font-mono tracking-widest uppercase"
					/>
					<Button type="submit" className="mt-2 w-full" disabled={!code.trim()}>
						Continue
					</Button>
				</form>
			</DeviceShell>
		);
	}

	// claiming | ready
	return (
		<DeviceShell>
			<h1 className="mt-5 mb-1 text-lg font-medium">Connect your terminal</h1>
			<p className="mb-5 text-sm text-muted-foreground text-balance">
				Connect to your Foglamp account
				{userEmail ? (
					<>
						{" "}
						(<span className="text-foreground">{userEmail}</span>)
					</>
				) : null}{" "}
				and create an API key. Only approve this if you started it.
			</p>

			<Card className="mb-6 flex items-center justify-center bg-muted px-4 py-3">
				<code className="font-mono text-base tracking-widest uppercase">
					{code || "—"}
				</code>
			</Card>

			<div className="flex flex-col gap-2.5">
				<Button
					className="w-full"
					disabled={phase !== "ready" || busy}
					onClick={() => void decide("approve")}
				>
					{phase === "claiming"
						? "Verifying…"
						: busy
							? "Connecting…"
							: "Approve & connect"}
				</Button>
				<Button
					variant="ghost"
					className="w-full text-muted-foreground"
					disabled={phase !== "ready" || busy}
					onClick={() => void decide("deny")}
				>
					Deny
				</Button>
			</div>
		</DeviceShell>
	);
}

/**
 * Original design by Gustavo Fior (@gustavo-fior), co-founder Abdul Haidar, and Foglamp Labs.
 * Composed AS-IS from foglamp-labs/foglamp auth and onboarding modules.
 * Licensed under Apache-2.0.
 */
export * from "./login-form";
export * from "./device-approve";
export * from "./onboarding-panel";
export * from "./instrument-empty-state";
export * from "./buttons-badges";

/**
 * Original design by Gustavo Fior (@gustavo-fior), co-founder Abdul Haidar, and Foglamp Labs.
 * Extracted AS-IS from foglamp-labs/foglamp: apps/web/src/components/app/instrument-empty-state.tsx.
 * Licensed under Apache-2.0.
 */
"use client";

import { Button } from "../../ui/button";
import {
  Empty,
  EmptyContent,
  EmptyDescription,
  EmptyHeader,
  EmptyMedia,
  EmptyTitle,
} from "../../ui/empty";
import { cn } from "../../lib/utils";
import { motion } from "motion/react";
import { useId, useState } from "react";

import { CodeBlock } from "../../widgets/code-block";
import { CopyIcon } from "../../widgets/leaf/copy-icon";
import { useCopied } from "../../hooks/use-copied";

// Same spring as ViewToggle, so segmented controls across the app glide
// identically.
const MORPH = { type: "spring", stiffness: 400, damping: 38 } as const;

type SdkVersion = "v7" | "v6";

const SDK_OPTIONS: { value: SdkVersion; label: string }[] = [
  { value: "v7", label: "v7" },
  { value: "v6", label: "v6 or lower" },
];

/** A two-option segmented control for switching between AI SDK snippets.
 * Sized to sit flush next to the CodeBlock's copy button. */
function SdkToggle({
  value,
  onChange,
}: {
  value: SdkVersion;
  onChange: (value: SdkVersion) => void;
}) {
  // Unique per instance so each mounted toggle owns its own sliding pill.
  const pillId = useId();
  return (
    <div className="inline-flex h-8 items-center rounded-full px-1 p-0.5 dark:bg-input/20 bg-card shadow-(--custom-shadow) dark:shadow-(--custom-shadow)">
      {SDK_OPTIONS.map((opt) => {
        const active = opt.value === value;
        return (
          <button
            key={opt.value}
            type="button"
            aria-pressed={active}
            onClick={() => onChange(opt.value)}
            className={cn(
              "relative flex h-6 cursor-pointer items-center justify-center rounded-full px-2.5 text-xs transition-colors",
              active
                ? "text-foreground"
                : "text-muted-foreground/60 hover:text-foreground"
            )}
          >
            {active && (
              <motion.span
                layoutId={pillId}
                transition={MORPH}
                className="absolute inset-0 rounded-full bg-input dark:bg-input/50"
              />
            )}
            <span className="relative z-10">{opt.label}</span>
          </button>
        );
      })}
    </div>
  );
}

// Empty state for the Agents / Workflows / Sessions pages: the usual dashed card
// plus a copy-pasteable instrumentation snippet, toggled between the AI SDK v7
// native path (`foglamp().integration`) and the v4–v6 wrapping path
// (`foglamp/wrap`).

export type InstrumentFeature = "agent" | "workflow" | "session";

const SNIPPETS: Record<InstrumentFeature, { v7: string; v6: string }> = {
  agent: {
    v7: `import { foglamp } from "foglamp";

const fog = foglamp();

await generateText({
  model,
  prompt,
  telemetry: {
    integrations: [fog.integration({ agentName: "my-agent" })],
  },
});`,
    v6: `import * as ai from "ai";
import { wrap } from "foglamp/wrap";

const { generateText } = wrap(ai, {
  context: { agentName: "my-agent" },
});

await generateText({ model, prompt });`,
  },
  workflow: {
    v7: `import { foglamp } from "foglamp";

const fog = foglamp();

await generateText({
  model,
  prompt,
  telemetry: {
    integrations: [
      fog.integration({
        workflowName: "nightly-digest",
        workflowRunId: run.id,
      }),
    ],
  },
});`,
    v6: `import * as ai from "ai";
import { wrap } from "foglamp/wrap";

const { generateText } = wrap(ai, {
  context: {
    workflowName: "nightly-digest",
    workflowRunId: run.id,
  },
});

await generateText({ model, prompt });`,
  },
  session: {
    v7: `import { foglamp } from "foglamp";

const fog = foglamp();

await generateText({
  model,
  prompt,
  telemetry: {
    integrations: [
      fog.integration({
        agentName: "support",
        sessionId: user.threadId,
      }),
    ],
  },
});`,
    v6: `import * as ai from "ai";
import { wrap } from "foglamp/wrap";

const { generateText } = wrap(ai, {
  context: {
    agentName: "support",
    sessionId: user.threadId,
  },
});

await generateText({ model, prompt });`,
  },
};

export type InstrumentEmptyStateBlockProps = {
  feature: InstrumentFeature;
  icon: React.ComponentType<{ className?: string }>;
  title: string;
  description?: string;
};

export function InstrumentEmptyStateBlock({
  feature,
  icon: Icon,
  title,
  description,
}: InstrumentEmptyStateBlockProps) {
  const snip = SNIPPETS[feature];
  const [version, setVersion] = useState<SdkVersion>("v7");
  const { copied, markCopied } = useCopied(2000);

  const copy = () => {
    void navigator.clipboard.writeText(snip[version]);
    markCopied();
  };

  return (
    <Empty className="border border-dashed">
      <EmptyHeader>
        <EmptyMedia variant="icon">
          <Icon className="opacity-40" />
        </EmptyMedia>
        <EmptyContent>
          <EmptyTitle>{title}</EmptyTitle>
          {description && <EmptyDescription>{description}</EmptyDescription>}
        </EmptyContent>
      </EmptyHeader>

      {/* Both snippets share one grid cell, so the row is always sized to the
          taller one — toggling never changes layout height (nothing above
          shifts). The inactive snippet stays in the layout at opacity-0 and we
          crossfade between them. `inert` keeps the hidden copy out of the tab
          order and clicks. The toggle + copy button live in a single overlay
          outside the fading layers so they hold steady while the code fades. */}
      <div className="relative grid w-full max-w-xl">
        {SDK_OPTIONS.map(({ value }) => {
          const active = value === version;
          return (
            <div
              key={value}
              inert={!active}
              className={cn(
                "col-start-1 row-start-1 transition-opacity duration-200",
                active ? "opacity-100" : "opacity-0"
              )}
            >
              <CodeBlock code={snip[value]} hideCopy />
            </div>
          );
        })}
        <div className="absolute right-3 top-3 flex items-center gap-1">
          <SdkToggle value={version} onChange={setVersion} />
          <Button
            size="icon-sm"
            variant="outline"
            className="text-muted-foreground hover:text-foreground dark:bg-input/20 bg-card"
            aria-label="Copy code"
            onClick={copy}
          >
            <CopyIcon copied={copied} />
          </Button>
        </div>
      </div>
    </Empty>
  );
}

/**
 * Original design by Gustavo Fior (@gustavo-fior), co-founder Abdul Haidar, and Foglamp Labs.
 * Extracted AS-IS from foglamp-labs/foglamp: apps/web/src/components/login-form.tsx.
 * Licensed under Apache-2.0.
 */
"use client";

import { Button } from "../../ui/button";
import { Input } from "../../ui/input";
import { Label } from "../../ui/label";
import { useForm } from "@tanstack/react-form";
import { useState } from "react";
import { toast } from "sonner";
import z from "zod";

import { GoogleLogo } from "../../icons/brand-logos";
import { BrandMark } from "../marketing/chrome/brand-mark";

// Which sign-in methods the host application has enabled. Hosted: google +
// magic link. Self-host: password (+ magic link when email is configured).
export type AuthMethods = {
  emailPassword: boolean;
  magicLink: boolean;
  google: boolean;
};

export type LoginFormActionResult =
  | { kind: "success" }
  | { kind: "error"; message: string };

export type LoginFormCompletion =
  | { method: "google"; callbackURL: string }
  | { method: "password"; email: string; callbackURL: string };

export type LoginFormBlockProps = {
  methods?: AuthMethods;
  /** Sanitized same-site path to return to after sign-in. */
  next?: string | null;
  /** Local route used by a host application's reset-password flow. */
  resetPasswordHref?: string;
  onGoogleSignIn?: (input: {
    callbackURL: string;
  }) => Promise<LoginFormActionResult>;
  onPasswordSignIn?: (input: {
    email: string;
    password: string;
    callbackURL: string;
  }) => Promise<LoginFormActionResult>;
  onPasswordReset?: (input: {
    email: string;
    redirectTo: string;
  }) => Promise<LoginFormActionResult>;
  onMagicLinkSignIn?: (input: {
    email: string;
    callbackURL: string;
  }) => Promise<LoginFormActionResult>;
  onSignedIn?: (completion: LoginFormCompletion) => void;
};

const DEFAULT_METHODS: AuthMethods = {
  emailPassword: true,
  magicLink: true,
  google: true,
};

const LOCAL_SUCCESS: LoginFormActionResult = { kind: "success" };

function getErrorMessage(error: unknown, fallback: string): string {
  return error instanceof Error && error.message ? error.message : fallback;
}

export function LoginFormBlock({
  methods = DEFAULT_METHODS,
  next,
  resetPasswordHref = "/reset-password",
  onGoogleSignIn,
  onPasswordSignIn,
  onPasswordReset,
  onMagicLinkSignIn,
  onSignedIn,
}: LoginFormBlockProps) {
  // The host can apply its origin while this standalone block keeps route
  // selection portable across TanStack Start, Next.js, and plain React apps.
  const callbackURL = next ?? "/overview";
  // Password first when available (the self-host floor); otherwise magic link.
  const [mode, setMode] = useState<"password" | "magic" | "forgot">(
    methods.emailPassword ? "password" : "magic"
  );
  const [sentTo, setSentTo] = useState<string | null>(null);
  const [resetSentTo, setResetSentTo] = useState<string | null>(null);
  const [googlePending, setGooglePending] = useState(false);
  const [signInComplete, setSignInComplete] = useState<
    | { kind: "google"; localDemo: boolean }
    | { kind: "password"; email: string; localDemo: boolean }
    | null
  >(null);

  const hasEmailForm =
    ((mode === "password" || mode === "forgot") && methods.emailPassword) ||
    (mode === "magic" && methods.magicLink);

  const signInWithGoogle = async () => {
    setGooglePending(true);
    try {
      const result = onGoogleSignIn
        ? await onGoogleSignIn({ callbackURL })
        : LOCAL_SUCCESS;
      if (result.kind === "error") {
        toast.error(result.message || "Google sign-in failed. Try again.");
        return;
      }
      setSignInComplete({
        kind: "google",
        localDemo: onGoogleSignIn === undefined,
      });
      onSignedIn?.({ method: "google", callbackURL });
    } catch (error) {
      toast.error(getErrorMessage(error, "Google sign-in failed. Try again."));
    } finally {
      setGooglePending(false);
    }
  };

  const passwordForm = useForm({
    defaultValues: { email: "", password: "" },
    onSubmit: async ({ value }) => {
      try {
        const result = onPasswordSignIn
          ? await onPasswordSignIn({
              email: value.email,
              password: value.password,
              callbackURL,
            })
          : LOCAL_SUCCESS;
        if (result.kind === "error") {
          toast.error(result.message || "Invalid email or password.");
          return;
        }
        setSignInComplete({
          kind: "password",
          email: value.email,
          localDemo: onPasswordSignIn === undefined,
        });
        onSignedIn?.({
          method: "password",
          email: value.email,
          callbackURL,
        });
      } catch (error) {
        toast.error(getErrorMessage(error, "Invalid email or password."));
      }
    },
    validators: {
      onSubmit: z.object({
        email: z.email("Enter a valid email."),
        password: z.string().min(1, "Enter your password."),
      }),
    },
  });

  const forgotForm = useForm({
    defaultValues: { email: "" },
    onSubmit: async ({ value }) => {
      try {
        const result = onPasswordReset
          ? await onPasswordReset({
              email: value.email,
              redirectTo: resetPasswordHref,
            })
          : LOCAL_SUCCESS;
        if (result.kind === "error") {
          toast.error(result.message || "Could not send the reset email.");
          return;
        }
        setResetSentTo(value.email);
      } catch (error) {
        toast.error(getErrorMessage(error, "Could not send the reset email."));
      }
    },
    validators: {
      onSubmit: z.object({ email: z.email("Enter a valid email.") }),
    },
  });

  const magicForm = useForm({
    defaultValues: { email: "" },
    onSubmit: async ({ value }) => {
      try {
        const result = onMagicLinkSignIn
          ? await onMagicLinkSignIn({
              email: value.email,
              callbackURL,
            })
          : LOCAL_SUCCESS;
        if (result.kind === "error") {
          toast.error(
            result.message || "Magic-link sign-in isn't enabled on this instance."
          );
          return;
        }
        setSentTo(value.email);
      } catch (error) {
        toast.error(
          getErrorMessage(
            error,
            "Magic-link sign-in isn't enabled on this instance."
          )
        );
      }
    },
    validators: {
      onSubmit: z.object({ email: z.email("Enter a valid email.") }),
    },
  });

  if (signInComplete) {
    return (
      <div className="mx-auto flex w-full max-w-lg flex-col gap-4 p-6">
        <div className="size-10 rounded-md squircle:rounded-2xl corner-squircle shadow-(--custom-shadow) bg-muted flex justify-center items-center">
          <BrandMark className="w-7" />
        </div>
        <div className="mt-3 flex flex-col gap-2">
          <h1 className="text-xl font-medium text-balance">
            {signInComplete.kind === "google"
              ? signInComplete.localDemo
                ? "Local Google sign-in complete"
                : "Google sign-in complete"
              : "Signed in"}
          </h1>
          <p className="text-sm text-muted-foreground mt-0.5">
            {signInComplete.kind === "google"
              ? signInComplete.localDemo
                ? "Your local sign-in flow is complete."
                : "Your Google sign-in flow is complete."
              : signInComplete.localDemo
                ? `Signed in locally as ${signInComplete.email}.`
                : `Signed in as ${signInComplete.email}.`}
          </p>
        </div>
        <Button
          variant="link"
          className="self-start px-0"
          onClick={() => setSignInComplete(null)}
        >
          Back to login
        </Button>
      </div>
    );
  }

  if (resetSentTo) {
    return (
      <div className="mx-auto flex w-full max-w-lg flex-col gap-4 p-6">
        <div className="size-10 rounded-md squircle:rounded-2xl corner-squircle shadow-(--custom-shadow) bg-muted flex justify-center items-center">
          <BrandMark className="w-7" />
        </div>
        <div className="mt-3 flex flex-col gap-2">
          <h1 className="text-xl font-medium text-balance">Check your email</h1>
          <p className="text-sm text-muted-foreground mt-0.5">
            If an account exists for{" "}
            <span className="font-medium text-foreground">{resetSentTo}</span>,
            we sent it a password reset link.
          </p>
          <p className="text-sm text-muted-foreground text-balance mt-2">
            The link expires in{" "}
            <span className="text-foreground font-medium">1 hour</span>.
          </p>
        </div>
        <Button
          className="self-start mt-2"
          onClick={() => {
            setResetSentTo(null);
            setMode("password");
          }}
        >
          Back to login
        </Button>
      </div>
    );
  }

  if (sentTo) {
    return (
      <div className="mx-auto flex w-full max-w-lg flex-col gap-4 p-6">
        <div className="size-10 rounded-md squircle:rounded-2xl corner-squircle shadow-(--custom-shadow) bg-muted flex justify-center items-center">
          <BrandMark className="w-7" />
        </div>
        <div className="mt-5 flex flex-col gap-2">
          <h1 className="text-xl font-medium text-balance">Check your email</h1>
          <p className="text-sm text-muted-foreground mt-0.5">
            We sent a sign-in link to{" "}
            <span className="font-medium text-foreground">{sentTo}</span>.
          </p>
          <p className="text-sm text-muted-foreground text-balance">
            The link expires in 15 minutes.
          </p>
        </div>
        <Button
          variant="link"
          className="self-start px-0"
          onClick={() => {
            setSentTo(null);
            setMode(methods.emailPassword ? "password" : "magic");
          }}
        >
          Back to login
        </Button>
      </div>
    );
  }

  return (
    <div className="mx-auto flex w-full max-w-lg flex-col p-6">
      <div className="size-10 rounded-md squircle:rounded-2xl corner-squircle bg-muted shadow-(--custom-shadow) flex justify-center items-center">
        <BrandMark className="w-7" />
      </div>
      <h1 className="mt-5 mb-1 w-full text-start text-lg font-medium text-balance">
        {mode === "forgot" ? "Reset your password" : "Login"}
      </h1>
      <p className="mb-6 text-sm text-muted-foreground tracking-normal">
        {mode === "forgot"
          ? "We'll email you a link to choose a new password."
          : "Sign in to your Foglamp account to continue."}
      </p>

      {methods.google && mode !== "forgot" && (
        <Button
          type="button"
          variant="secondary"
          className="w-full"
          disabled={googlePending}
          onClick={signInWithGoogle}
        >
          <GoogleLogo className="size-3.5 mr-0.75" />
          {googlePending ? "Redirecting…" : "Continue with Google"}
        </Button>
      )}

      {methods.google && hasEmailForm && mode !== "forgot" && (
        <div className="my-5 flex items-center gap-3">
          <div className="h-px flex-1 bg-border/50" />
          <span className="text-xs text-muted-foreground/60">or</span>
          <div className="h-px flex-1 bg-border/50" />
        </div>
      )}

      {hasEmailForm && mode === "password" ? (
        <form
          onSubmit={(e) => {
            e.preventDefault();
            e.stopPropagation();
            passwordForm.handleSubmit();
          }}
          className="flex w-full flex-col gap-5"
        >
          <passwordForm.Field name="email">
            {(field) => (
              <div className="flex flex-col gap-2.5">
                <Label htmlFor={field.name}>Email</Label>
                <Input
                  id={field.name}
                  name={field.name}
                  type="email"
                  autoComplete="email"
                  placeholder="you@example.com"
                  value={field.state.value}
                  onBlur={field.handleBlur}
                  onChange={(e) => field.handleChange(e.target.value)}
                />
                {field.state.meta.errors.map((error) => (
                  <p key={error?.message} className="text-xs text-destructive">
                    {error?.message}
                  </p>
                ))}
              </div>
            )}
          </passwordForm.Field>

          <passwordForm.Field name="password">
            {(field) => (
              <div className="flex flex-col gap-2.5">
                <div className="flex items-center justify-between">
                  <Label htmlFor={field.name}>Password</Label>
                  <button
                    type="button"
                    className="text-xs text-muted-foreground hover:text-foreground cursor-pointer transition-colors"
                    onClick={() => setMode("forgot")}
                  >
                    Forgot password?
                  </button>
                </div>
                <Input
                  id={field.name}
                  name={field.name}
                  type="password"
                  autoComplete="current-password"
                  placeholder="••••••••"
                  value={field.state.value}
                  onBlur={field.handleBlur}
                  onChange={(e) => field.handleChange(e.target.value)}
                />
                {field.state.meta.errors.map((error) => (
                  <p key={error?.message} className="text-xs text-destructive">
                    {error?.message}
                  </p>
                ))}
              </div>
            )}
          </passwordForm.Field>

          <passwordForm.Subscribe
            selector={(state) => ({
              canSubmit: state.canSubmit,
              isSubmitting: state.isSubmitting,
            })}
          >
            {({ canSubmit, isSubmitting }) => (
              <Button
                type="submit"
                className="w-full mt-2"
                disabled={!canSubmit || isSubmitting}
              >
                {isSubmitting ? "Signing in…" : "Login"}
              </Button>
            )}
          </passwordForm.Subscribe>
        </form>
      ) : hasEmailForm && mode === "forgot" ? (
        <form
          onSubmit={(e) => {
            e.preventDefault();
            e.stopPropagation();
            forgotForm.handleSubmit();
          }}
          className="flex w-full flex-col gap-5"
        >
          <forgotForm.Field name="email">
            {(field) => (
              <div className="flex flex-col gap-2.5">
                <Input
                  id={field.name}
                  name={field.name}
                  type="email"
                  autoComplete="email"
                  placeholder="you@example.com"
                  value={field.state.value}
                  onBlur={field.handleBlur}
                  onChange={(e) => field.handleChange(e.target.value)}
                />
                {field.state.meta.errors.map((error) => (
                  <p key={error?.message} className="text-xs text-destructive">
                    {error?.message}
                  </p>
                ))}
              </div>
            )}
          </forgotForm.Field>

          <forgotForm.Subscribe
            selector={(state) => ({
              canSubmit: state.canSubmit,
              isSubmitting: state.isSubmitting,
            })}
          >
            {({ canSubmit, isSubmitting }) => (
              <Button
                type="submit"
                className="w-full mt-1"
                disabled={!canSubmit || isSubmitting}
              >
                {isSubmitting ? "Sending…" : "Send reset link"}
              </Button>
            )}
          </forgotForm.Subscribe>

          <Button
            type="button"
            variant="link"
            className="self-start px-0 text-muted-foreground/50"
            onClick={() => setMode("password")}
          >
            Back to login
          </Button>
        </form>
      ) : hasEmailForm ? (
        <form
          onSubmit={(e) => {
            e.preventDefault();
            e.stopPropagation();
            magicForm.handleSubmit();
          }}
          className="flex w-full flex-col gap-6"
        >
          <magicForm.Field name="email">
            {(field) => (
              <div className="flex flex-col gap-2.5">
                <Input
                  id={field.name}
                  name={field.name}
                  type="email"
                  autoComplete="email"
                  placeholder="you@example.com"
                  value={field.state.value}
                  onBlur={field.handleBlur}
                  onChange={(e) => field.handleChange(e.target.value)}
                />
                {field.state.meta.errors.map((error) => (
                  <p key={error?.message} className="text-xs text-destructive">
                    {error?.message}
                  </p>
                ))}
              </div>
            )}
          </magicForm.Field>

          <magicForm.Subscribe
            selector={(state) => ({
              canSubmit: state.canSubmit,
              isSubmitting: state.isSubmitting,
            })}
          >
            {({ canSubmit, isSubmitting }) => (
              <Button
                type="submit"
                className="w-full"
                disabled={!canSubmit || isSubmitting}
              >
                {isSubmitting ? "Sending…" : "Send sign-in link"}
              </Button>
            )}
          </magicForm.Subscribe>
        </form>
      ) : null}

      {methods.emailPassword && methods.magicLink && mode !== "forgot" && (
        <Button
          variant="link"
          className="mt-4 self-start px-0 text-muted-foreground/50 hover:text-foreground"
          onClick={() => setMode(mode === "password" ? "magic" : "password")}
        >
          {mode === "password"
            ? "Email me a sign-in link instead"
            : "Use email and password instead"}
        </Button>
      )}
    </div>
  );
}

